-- Safety guard: refuse to re-seed an already-initialised database.
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM information_schema.tables
                   WHERE table_schema = 'public' AND table_name = 'reference_data_version') THEN
        RAISE NOTICE 'Schema not found — run database/schema.sql first.';
    ELSIF EXISTS (SELECT 1 FROM reference_data_version WHERE dataset = 'maladies') THEN
        RAISE EXCEPTION 'Seed already applied (reference_data_version.maladies is set).'
                      ' Delete that row first if you really want to re-seed.';
    END IF;
END $$;

